def maximal_square_area(matrix):
    dp = [0] * (len(matrix[0]) + 1)
    best = 0
    for row in matrix:
        diagonal = 0
        for column, char in enumerate(row, 1):
            above = dp[column]
            if char == "1":
                dp[column] = 1 + min(above, dp[column - 1], diagonal)
                best = max(best, dp[column])
            else:
                dp[column] = 0
            diagonal = above
    return best * best

